# Create-only new read-only checker; existing checker/runner/data unchanged.
import base64,hashlib,json,os,stat,uuid,zlib
from pathlib import Path
DIRECTORY=Path('/offmenu/scripts/windmill')
OLD=DIRECTORY/'platform_check.py'
NEW=DIRECTORY/'platform_check_capacity64.py'
OLD_SHA='03f61831f020fdbb5152d1ffbfd656966768559225b3fe1c72b24b2a91aa2957'
NEW_SHA='ca919ab491685c9b60bad9ff827b8da3e77ae5d3ec06424c160a8c386e2b2334'
PAYLOAD=''

def read_regular(p):
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
 with os.fdopen(fd,'rb') as f:
  s=os.fstat(f.fileno())
  if not stat.S_ISREG(s.st_mode) or s.st_size>65536:raise RuntimeError('SourceTypeRefused')
  return f.read(65537)

for p in (DIRECTORY,*DIRECTORY.parents):
 if p.is_symlink():raise RuntimeError('SymlinkParentRefused')
b=zlib.decompress(base64.b64decode(PAYLOAD,validate=True))
if len(b)>65536 or hashlib.sha256(b).hexdigest()!=NEW_SHA:raise RuntimeError('PayloadMismatch')
compile(b,str(NEW),'exec')
if hashlib.sha256(read_regular(OLD)).hexdigest()!=OLD_SHA:raise RuntimeError('OldPreimageMismatch')
temp=None
try:
 if NEW.exists():
  if hashlib.sha256(read_regular(NEW)).hexdigest()!=NEW_SHA:raise RuntimeError('ExistingVersionMismatch')
  outcome='already_present_exact'
 else:
  temp=DIRECTORY/('.health64-'+uuid.uuid4().hex)
  fd=os.open(temp,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o660)
  with os.fdopen(fd,'wb') as f:f.write(b);f.flush();os.fsync(f.fileno())
  os.link(temp,NEW,follow_symlinks=False);temp.unlink();temp=None
  fd=os.open(DIRECTORY,os.O_DIRECTORY)
  try:os.fsync(fd)
  finally:os.close(fd)
  outcome='created_new_version'
 if hashlib.sha256(read_regular(NEW)).hexdigest()!=NEW_SHA:raise RuntimeError('ReadbackMismatch')
 print(json.dumps({'status':outcome,'sha256':NEW_SHA,'old_checker_unchanged':hashlib.sha256(read_regular(OLD)).hexdigest()==OLD_SHA}))
finally:
 if temp is not None and temp.exists():temp.unlink()
